Here is an example of a complete React component for a shopping cart with state management using Redux Toolkit:

**Components**

First, create a new file called `Cart.js` in the `src` directory:
```jsx
// src/Cart.js
import React from'react';
import { useSelector, useDispatch } from'react-redux';
import { CSSTransition } from'react-transition-group';
import { Button, Form, ListGroup, ListGroupItem } from'reactstrap';
import { removeFromCart, updateQuantity, checkout } from './cartSlice';

const Cart = () => {
  const dispatch = useDispatch();
  const cart = useSelector((state) => state.cart);

  const handleRemoveFromCart = (productId) => {
    dispatch(removeFromCart(productId));
  };

  const handleUpdateQuantity = (productId, quantity) => {
    dispatch(updateQuantity({ productId, quantity }));
  };

  const handleCheckout = () => {
    dispatch(checkout());
  };

  return (
    <CSSTransition in={cart.isOpen} timeout={500} classNames="cart">
      <div className="cart">
        <h2>Shopping Cart</h2>
        <Form>
          <ListGroup>
            {cart.items.map((item) => (
              <ListGroupItem key={item.productId}>
                <div>
                  <img src={item.image} alt={item.name} />
                  <h4>{item.name}</h4>
                  <p>
                    {item.price} x {item.quantity} =
                    {item.price * item.quantity}
                  </p>
                  <Button
                    color="danger"
                    onClick={() => handleRemoveFromCart(item.productId)}
                  >
                    Remove
                  </Button>
                  <Button
                    color="success"
                    onClick={() => handleUpdateQuantity(item.productId, item.quantity + 1)}
                  >
                    +
                  </Button>
                  <Button
                    color="warning"
                    onClick={() => handleUpdateQuantity(item.productId, item.quantity - 1)}
                  >
                    -
                  </Button>
                </div>
              </ListGroupItem>
            ))}
          </ListGroup>
          <Button color="primary" onClick={handleCheckout}>
            Checkout
          </Button>
        </Form>
      </div>
    </CSSTransition>
  );
};

export default Cart;
```
